<?php
declare(strict_types=1);

function render_users_module(array $user): void
{
    $users = db()->query('SELECT id,name,username,role,active,last_login FROM users ORDER BY name')->fetchAll();
    ?>
    <section class="panel"><div class="panel-heading"><div><h2>User accounts</h2><p>Roles provide access to assigned workflow stages; they do not grant formal signing authority.</p></div><button class="button primary" type="button" data-open-user>+ Add user</button></div>
        <div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Last sign in</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $account): $grantQuery = db()->prepare('SELECT stage FROM user_stage_access WHERE user_id=?'); $grantQuery->execute([$account['id']]); $accountStages = $grantQuery->fetchAll(PDO::FETCH_COLUMN); if (!$accountStages && $account['role'] !== 'Administrator' && $account['role'] !== 'Viewer / Management') $accountStages = array_values(array_filter(array_keys(STAGES), static fn(string $key): bool => STAGES[$key]['role'] === $account['role'])); if ($account['role'] === 'Administrator') $accountStages = array_keys(STAGES); ?><tr><td><?= h($account['name']) ?></td><td><?= h($account['username']) ?></td><td><?= h($account['role']) ?></td><td><span class="status <?= $account['active'] ? 'complete' : 'hold' ?>"><?= $account['active'] ? 'Active' : 'Inactive' ?></span></td><td><?= h($account['last_login'] ?: '—') ?></td><td><button class="text-link" type="button" data-edit-user="<?= h(json_encode($account, JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_TAG | JSON_HEX_AMP)) ?>" data-user-stages="<?= h(json_encode($accountStages)) ?>">Edit</button> <?php if ((int)$account['id'] !== (int)$user['id']): ?><form method="post" class="inline-form" data-confirm="Change this account's active status?"><?= csrf_field() ?><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><button class="text-link"><?= $account['active'] ? 'Deactivate' : 'Activate' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
    <dialog id="user-dialog"><form method="post" class="form-stack dialog-form"><?= csrf_field() ?><input type="hidden" name="action" value="save_user"><input type="hidden" name="id" value=""><h2>User account</h2><label>Full name<input name="name" required minlength="2" maxlength="120"></label><label>Username<input name="username" required pattern="[a-zA-Z0-9._\-]{3,60}"></label><label>Role<select name="role"><?php foreach (APP_ROLES as $role): ?><option><?= h($role) ?></option><?php endforeach; ?></select></label><fieldset class="permission-list"><legend>Workflow permissions</legend><?php foreach (STAGES as $stage => $info): ?><label class="check-label"><input type="checkbox" name="stages[]" value="<?= h($stage) ?>"> <?= h($info['label']) ?></label><?php endforeach; ?><small>Administrators always have all permissions. Viewer / Management accounts can leave all stages unchecked for read-only access; other accounts need at least one selected stage.</small></fieldset><label>Password <small>(minimum 12 characters; leave blank when unchanged)</small><input name="password" type="password" minlength="12"></label><div class="form-actions"><button type="button" class="button secondary" data-close-dialog>Cancel</button><button class="button primary">Save user</button></div></form></dialog>
    <?php
}
